const updatePage = `-- name: UpdatePage :one
UPDATE app.pages SET title_fa = $1, title_en = $2, body_fa = $3,
  body_en = $4, published = $5, version = version + 1, updated_by = $6
WHERE slug = $7 AND version = $8
RETURNING slug, title_fa, title_en, body_fa, body_en, published, version, updated_at
`

type UpdatePageParams struct {
	TitleFa         string
	TitleEn         pgtype.Text
	BodyFa          string
	BodyEn          pgtype.Text
	Published       bool
	Actor           pgtype.UUID
	Slug            string
	ExpectedVersion int32
}

type UpdatePageRow struct {
	Slug      string
	TitleFa   string
	TitleEn   pgtype.Text
	BodyFa    string
	BodyEn    pgtype.Text
	Published bool
	Version   int32
	UpdatedAt pgtype.Timestamptz
}

// Optimistic lock: no row when someone saved a newer version in between.
func (q *Queries) UpdatePage(ctx context.Context, arg UpdatePageParams) (UpdatePageRow, error) {
	row := q.db.QueryRow(ctx, updatePage,
		arg.TitleFa,
		arg.TitleEn,
		arg.BodyFa,
		arg.BodyEn,
		arg.Published,
		arg.Actor,
		arg.Slug,
		arg.ExpectedVersion,
	)
	var i UpdatePageRow
	err := row.Scan(
		&i.Slug,
		&i.TitleFa,
		&i.TitleEn,
		&i.BodyFa,
		&i.BodyEn,
		&i.Published,
		&i.Version,
		&i.UpdatedAt,
	)
	return i, err
}
